@@ -724,4 +724,3 @@
-// Fold a single-bit constant mask into the immediate Zbs instructions. Masks
-// that fit in a signed 12-bit immediate are handled by ori/xori/andi instead.
-instruct orL_reg_immL_SingleBit(iRegLNoSp dst, iRegL src, immL_SingleBitNotSimm12 mask) %{
-  predicate(UseZbs);
+// Prefer ori/xori/andi when the mask fits in a signed 12-bit immediate.
+instruct orL_reg_immL_SingleBit(iRegLNoSp dst, iRegL src, immL_single_bit mask) %{
+  predicate(UseZbs && !Assembler::is_simm12(n->in(2)->get_long()));
